ast.DefineStruct("SyntaxList", { "NodeBase" })

function NodeFactory:NewSyntaxList(children)
    local data = setmetatable({
        children = children,
    }, ast.SyntaxList)
    return self:newNode(Kind.SyntaxList, data)
end

function NodeFactory:UpdateSyntaxList(node, children)
    if not core.Same(children, node.children) then
        return ast.updateNode(self:NewSyntaxList(children), node, self.hooks)
    end
    return node
end

function ast.SyntaxList:ForEachChild(v)
    return ast.visitNodes(v, self.children)
end

function ast.SyntaxList:VisitEachChild(v)
    local children = core.SameMap(self.children, function(n) return v:visitNode(n) end)
    return v.factory:UpdateSyntaxList(self, children)
end

function ast.SyntaxList:Clone(f)
    return ast.cloneNode(f:AsNodeFactory():NewSyntaxList(self.children), self, f:AsNodeFactory().hooks)
end

function ast.IsSyntaxList(node)
    return node.kind == Kind.SyntaxList
end

