-- ──────────────────────────────────────────────────────────────────────
-- Kind alias guards
-- ──────────────────────────────────────────────────────────────────────

ast.IsTriviaKind_kinds = {
    [Kind.SingleLineCommentTrivia] = true,
    [Kind.MultiLineCommentTrivia] = true,
    [Kind.NewLineTrivia] = true,
    [Kind.WhitespaceTrivia] = true,
    [Kind.ConflictMarkerTrivia] = true,
}
function ast.IsTriviaKind(kind)
